import jsonfrom copy import deepcopyfrom datetime import UTC, datetime, timedeltafrom decimal import ROUND_HALF_UP, Decimalimport pytestfrom vpars_bot.domain import PRICE_PROMPT, Filters, UserError, parse_pricefrom vpars_bot.exchange import ExchangeRates, ExchangeRateUnavailable, parse_ecbfrom vpars_bot.keyword_dialog import build_filters, input_value, new_filter_draft, render_draft@pytest.mark.parametrize("brand", ["Nike", "Adidas", "Amiri"])@pytest.mark.parametrize(    "value,low,high",    [("20 80", "20", "80"), ("80,50", None, "80.50"), ("20 -", "20", None), ("0", None, "0")],)def test_one_euro_question_for_every_market(registry, brand, value, low, high):    draft = new_filter_draft(registry)    draft = input_value(draft, brand, 1)    draft = input_value(draft, "", 2, skip=True)    assert render_draft(draft, registry)[0] == PRICE_PROMPT    draft = input_value(draft, value, 3)    assert draft["step"] == "complete"    filters = build_filters(draft, registry)    assert filters.price == parse_price(value, "EUR")    assert filters.native_prices == {}    for source in registry.sources:        price = registry.for_source(filters, source).price        factor = Decimal("0.85") if source == "vinted_gb" else Decimal(1)        assert price.minimum == (Decimal(low) * factor if low is not None else None)        expected = (            (Decimal(high) * factor).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)            if high is not None            else None        )        assert price.maximum == expected@pytest.mark.parametrize("legacy", [False, True])def test_rates_refresh_existing_filters_without_modifying_saved_settings(registry, legacy):    values = {"minimum": "20", "maximum": "80"}    filters = Filters(        keywords=["Adidas"],        excluded_keywords=["Fake"],        sources={"vinted_gb": ["GB"], "vinted_fr": ["FR"]},        **(            {"native_prices": {"EUR": values, "GBP": {"maximum": "1"}}}            if legacy            else {"price": {"currency": "EUR", **values}}        ),    )    original = deepcopy(filters.model_dump())    assert registry.for_source(filters, "vinted_gb").price.maximum == Decimal("68")    registry.exchange.load({"date": datetime.now(UTC).date().isoformat(), "rates": {"GBP": "0.9"}})    assert registry.for_source(filters, "vinted_gb").price.maximum == Decimal("72")    assert filters.model_dump() == originaldef test_missing_expired_rates_block_only_converted_bounds(registry):    filters = Filters(        price={"currency": "EUR", "maximum": "80"},        sources={"vinted_gb": ["GB"], "vinted_fr": ["FR"]},    )    registry.exchange = ExchangeRates()    with pytest.raises(UserError, match="Курс"):        registry.for_source(filters, "vinted_gb")    assert registry.for_source(filters, "vinted_fr").price.maximum == 80    assert (        registry.for_source(filters.model_copy(update={"price": None}), "vinted_gb").price is None    )    registry.exchange.as_of = datetime.now(UTC).date() - timedelta(days=8)    registry.exchange.rates = {"GBP": Decimal("0.85")}    with pytest.raises(ExchangeRateUnavailable):        registry.exchange.convert(Decimal(80), "GBP")@pytest.mark.parametrize("rate", ["NaN", "Infinity", "-1", "0"])def test_invalid_provider_rates_cannot_replace_cache(rate):    exchange = ExchangeRates()    today = datetime.now(UTC).date().isoformat()    exchange.load({"date": today, "rates": {"GBP": "0.85"}})    with pytest.raises(ValueError):        exchange.load({"date": today, "rates": {"GBP": rate}})    assert exchange.convert(Decimal(100), "GBP") == 85def test_ecb_xml_direction_and_rounding():    today = datetime.now(UTC).date().isoformat()    payload = f'<Envelope xmlns="urn:ecb"><Cube><Cube time="{today}"><Cube currency="GBP" rate="0.86525"/></Cube></Cube></Envelope>'    exchange = ExchangeRates()    exchange.load(parse_ecb(payload))    assert exchange.convert(Decimal("100"), "GBP") == Decimal("86.53")@pytest.mark.parametrize("age,available", [(0, True), (8, False)])async def test_outage_uses_only_recent_cache(monkeypatch, age, available):    class Cache:        async def get(self, key):            day = datetime.now(UTC).date() - timedelta(days=age)            return json.dumps({"date": day.isoformat(), "rates": {"GBP": "0.85"}})    def offline(**kwargs):        raise OSError("offline")    monkeypatch.setattr("vpars_bot.exchange.ClientSession", offline)    rates = ExchangeRates()    assert not await rates.refresh(Cache())    assert rates.refresh_seconds == 60    if available:        assert rates.convert(Decimal(100), "GBP") == 85    else:        with pytest.raises(ExchangeRateUnavailable):            rates.convert(Decimal(100), "GBP")